function toggleTracebackView() {
	const tracebackContainer = document.getElementById("traceback-container");
	const plaintextView = document.getElementById("plaintext-view");
	const interactiveView = document.getElementById("interactive-view");
	const toggleButton = document.getElementById("toggle-view-button");

	if (tracebackContainer.classList.contains("plaintext-view")) {
		tracebackContainer.classList.remove("plaintext-view");
		tracebackContainer.classList.add("interactive-view");
		plaintextView.style.display = "none";
		interactiveView.style.display = "block";
		toggleButton.textContent = "Plaintext view";
	} else {
		tracebackContainer.classList.remove("interactive-view");
		tracebackContainer.classList.add("plaintext-view");
		plaintextView.style.display = "block";
		interactiveView.style.display = "none";
		toggleButton.textContent = "Interactive view";
	}
}

function copyTraceback() {
	const plaintextView = document.getElementById("plaintext-view");
	const tracebackText = plaintextView.textContent;

	if (navigator.clipboard && navigator.clipboard.writeText) {
		navigator.clipboard.writeText(tracebackText).then(
			() => {
				console.log("Traceback copied to clipboard");
			},
			(err) => {
				console.error("Failed to copy traceback: ", err);
			}
		);
	} else {
		console.error("Clipboard API not available");
	}
}

